<body>
<div class="container">
  <h1>Angol–Magyar Kártyák</h1>
  <p class="subtitle">Kattints a kártyákra, hogy megforduljanak és tanulj!</p>

  <div class="scoreboard">
    <div class="score-item">
      <div class="score-label">Megfordított kártyák</div>
      <div class="score-value" id="flippedCount">0</div>
    </div>
    <div class="score-item">
      <div class="score-label">Összes kártya</div>
      <div class="score-value" id="totalCount">0</div>
    </div>
  </div>

  <div class="cards-grid" id="cardsGrid"></div>

  <div class="controls">
    <button class="primary" id="resetBtn">Újrakezdés</button>
    <button id="flipAllBtn">Mind megfordítása</button>
  </div>

  <div class="status" id="statusMessage" role="status" aria-live="polite">
    Kezdd el a tanulást! Kattints bármelyik kártyára.
  </div>
</div>

<script>
const WORDS = [
  { en: 'cat', hu: 'macska', emoji: '🐱', category: 'Állatok' },
  { en: 'dog', hu: 'kutya', emoji: '🐶', category: 'Állatok' },
  { en: 'bird', hu: 'madár', emoji: '🐦', category: 'Állatok' },
  { en: 'fish', hu: 'hal', emoji: '🐟', category: 'Állatok' },
  { en: 'red', hu: 'piros', emoji: '🔴', category: 'Színek' },
  { en: 'blue', hu: 'kék', emoji: '🔵', category: 'Színek' },
  { en: 'green', hu: 'zöld', emoji: '🟢', category: 'Színek' },
  { en: 'yellow', hu: 'sárga', emoji: '🟡', category: 'Színek' },
  { en: 'book', hu: 'könyv', emoji: '📚', category: 'Iskola' },
  { en: 'pencil', hu: 'ceruza', emoji: '✏️', category: 'Iskola' },
  { en: 'ruler', hu: 'vonalzó', emoji: '📏', category: 'Iskola' },
  { en: 'backpack', hu: 'táska', emoji: '🎒', category: 'Iskola' }
];

let flippedCards = new Set();

function saveState() {
  if (window.alfy && window.alfy.storage) {
    window.alfy.storage.set('flippedCards', Array.from(flippedCards));
  }
}

async function loadState() {
  if (window.alfy && window.alfy.storage) {
    try {
      const saved = await window.alfy.storage.get('flippedCards');
      if (saved && Array.isArray(saved)) {
        flippedCards = new Set(saved);
      }
    } catch (e) {
      console.error('Storage load error:', e);
    }
  }
}

function updateScore() {
  document.getElementById('flippedCount').textContent = flippedCards.size;
  document.getElementById('totalCount').textContent = WORDS.length;
}

function updateStatus() {
  const status = document.getElementById('statusMessage');
  const remaining = WORDS.length - flippedCards.size;
  if (remaining === 0) {
    status.textContent = '🎉 Remek! Minden kártyát megfordítottál!';
  } else if (remaining === 1) {
    status.textContent = 'Már csak 1 kártya van hátra!';
  } else if (flippedCards.size === 0) {
    status.textContent = 'Kezdd el a tanulást! Kattints bármelyik kártyára.';
  } else {
    status.textContent = `Még ${remaining} kártya van hátra. Folytasd!`;
  }
}

function createCard(word, index) {
  const container = document.createElement('div');
  container.className = 'card-container';

  const card = document.createElement('button');
  card.className = 'card';
  card.setAttribute('aria-label', `${word.en} - ${word.hu}. ${word.category}. Kattints a megfordításhoz.`);
  card.dataset.index = index;

  const front = document.createElement('div');
  front.className = 'card-face card-front';
  front.innerHTML = `
    <div class="card-emoji">${word.emoji}</div>
    <div class="card-word">${word.en}</div>
    <div class="card-category">${word.category}</div>
  `;

  const back = document.createElement('div');
  back.className = 'card-face card-back';
  back.innerHTML = `
    <div class="card-emoji">${word.emoji}</div>
    <div class="card-word">${word.hu}</div>
    <div class="card-category">${word.category}</div>
  `;

  card.appendChild(front);
  card.appendChild(back);
  container.appendChild(card);

  card.addEventListener('click', () => {
    card.classList.toggle('flipped');
    if (card.classList.contains('flipped')) {
      flippedCards.add(index);
    } else {
      flippedCards.delete(index);
    }
    updateScore();
    updateStatus();
    saveState();
  });

  if (flippedCards.has(index)) {
    card.classList.add('flipped');
  }

  return container;
}

function renderCards() {
  const grid = document.getElementById('cardsGrid');
  grid.innerHTML = '';
  WORDS.forEach((word, index) => {
    grid.appendChild(createCard(word, index));
  });
  updateScore();
  updateStatus();
}

document.getElementById('resetBtn').addEventListener('click', () => {
  flippedCards.clear();
  renderCards();
  saveState();
});

document.getElementById('flipAllBtn').addEventListener('click', () => {
  const allFlipped = flippedCards.size === WORDS.length;
  flippedCards.clear();
  if (!allFlipped) {
    WORDS.forEach((_, index) => flippedCards.add(index));
  }
  renderCards();
  saveState();
});

loadState().then(() => {
  renderCards();
});
</script>
</body>
</html>
